// Legal and policy pages for ClearWeek Studio.
//
// They describe how the store works: two digital products, one-time payments in USD with taxes
// included, payment on Stripe's hosted checkout, delivery by download link, no analytics, no
// advertising, no marketing email, no accounts. Coverage follows Stripe's website checklist
// (docs.stripe.com/get-started/checklist/website) and its business-website FAQ: business name,
// product descriptions, currency, customer service contacts, refund/return/cancellation and
// delivery policies, legal/export restrictions, privacy, business address, promotions terms
// and payment security. If the way the store works changes, these pages must change with it.
import { addressInline, esc, listJoin, mail, money, pageHeader, phone, sellerName } from "./ui.mjs";

function legalPage(ctx, { path, title, description, intro, summary, sections, nav }) {
  const { site } = ctx;
  const body = `
${pageHeader({ title, trail: [["/", "Home"], [path, title]] })}
<div class="container legal">
  <aside class="legal-toc">
    <details open>
      <summary>On this page</summary>
      <nav aria-label="On this page"><ol>${sections.map((s, i) => `<li><a href="#${s.id}">${i + 1}. ${esc(s.title)}</a></li>`).join("")}</ol></nav>
    </details>
  </aside>
  <article class="prose legal-body">
    <p class="updated">Last updated: <time datetime="${site.policiesUpdated}">${esc(site.policiesUpdatedDisplay)}</time></p>
    ${intro}
    ${summary ? `<div class="in-short"><h2>In short</h2><ul>${summary.map((s) => `<li>${s}</li>`).join("")}</ul><p class="small">This summary is for convenience. The full text below is what applies.</p></div>` : ""}
    ${sections.map((s, i) => `<section id="${s.id}" aria-labelledby="${s.id}-h"><h2 id="${s.id}-h"><span class="num">${i + 1}.</span> ${esc(s.title)}</h2>${s.html}</section>`).join("\n")}
  </article>
</div>`;
  return { path, title, description, body, nav };
}

const S = (id, title, html) => ({ id, title, html });

function contactTable(site) {
  return `<table class="kv"><tbody>
<tr><th scope="row">Business name</th><td>${esc(site.brand)}</td></tr>
${site.legalName ? `<tr><th scope="row">Legal name</th><td>${esc(site.legalName)}${site.entityType ? ` (${esc(site.entityType)})` : ""}</td></tr>` : ""}
<tr><th scope="row">Address</th><td>${esc(addressInline(site))}</td></tr>
<tr><th scope="row">Email</th><td>${mail(site)}</td></tr>
<tr><th scope="row">Phone</th><td>${phone(site)}</td></tr>
<tr><th scope="row">Website</th><td><a href="${esc(site.url)}/">${esc(site.domain)}</a></td></tr>
${site.registrationNumber ? `<tr><th scope="row">Registration number</th><td>${esc(site.registrationNumber)}</td></tr>` : ""}
${site.taxRegistration ? `<tr><th scope="row">Tax registration</th><td>${esc(site.taxRegistration)}</td></tr>` : ""}
</tbody></table>`;
}

const prices = (ctx) => ctx.products.products.map((p) => `the ${esc(p.name)} at ${money(p.price)}`);

// ---------------------------------------------------------------------------------------

export function terms(ctx) {
  const { site, products } = ctx;
  const [planner, bundle] = products.products;
  return legalPage(ctx, {
    path: "/terms/",
    title: "Terms and Conditions",
    description: `Terms and Conditions for buying digital planning templates from ${site.brand}: seller details, prices in USD, payment, digital delivery, license, refunds, withdrawal rights and governing law.`,
    intro: `<p>These Terms and Conditions (the “Terms”) apply to every purchase you make from ${esc(site.brand)} through ${esc(site.domain)} (the “website”). They explain what you're buying, how payment and delivery work, what you may do with the files, and what happens if something goes wrong. Please read them before you buy. You'll be asked to agree to them before you pay.</p>
<p class="callout">If you're a consumer, nothing in these Terms removes or limits the rights you have under the consumer protection laws of the country or state where you live.</p>`,
    summary: [
      `We sell two digital products: ${listJoin(prices(ctx))}. Both are downloadable files. Nothing is shipped.`,
      "Prices are in US dollars, include any tax we must collect, and are charged once. There are no subscriptions.",
      "Payment is handled by Stripe. We never see your full card number.",
      `You get a download page and an emailed link as soon as payment is confirmed. The link works for ${site.downloadLinkDays} days and we'll resend it free for ${site.redownloadMonths} months.`,
      "You may use the templates yourself and inside your own business or organization. You may not share, resell or publish them.",
      `Faulty or not as described? We fix it or refund you. Not downloaded yet? Full refund within ${site.unusedRefundDays} days.`,
    ],
    sections: [
      S("about", "About these Terms", `<p>These Terms, together with our <a href="/refund-policy/">Delivery and Refund Policy</a>, our <a href="/privacy/">Privacy Policy</a> and our <a href="/cookies/">Cookie Policy</a>, form the agreement between you and us for each purchase. If something in a policy conflicts with these Terms, these Terms apply, except where the policy gives you more rights.</p><p>In these Terms, “we”, “us” and “our” mean ${esc(site.brand)}. “You” means the person buying. “Products” or “files” means the digital templates we sell. A “consumer” is someone buying mainly for personal purposes rather than for a trade, business or profession.</p>`),
      S("seller", "Who we are", `<p>The seller is ${esc(sellerName(site))}, a business based in ${esc(site.address.city)}, ${esc(site.address.regionName)}, ${esc(site.address.country)}. You can reach us using the details below.</p>${contactTable(site)}`),
      S("eligibility", "Who can buy", `<ul><li>You must be at least 18 years old, or the age of majority where you live if that is higher. If you're younger, a parent or guardian must make the purchase.</li><li>Please give accurate details at checkout, especially your email address, because that's where we send your download link.</li><li>If you buy for a business, you confirm you're allowed to do so on its behalf. Some protections in these Terms apply only to consumers.</li><li>We can't sell to anyone located in a country or region subject to comprehensive U.S. sanctions, or to anyone on a U.S. government restricted-party list. If an order breaks this rule, we'll cancel it and refund the payment.</li></ul><p>Apart from these sanctions rules, we aren't aware of any legal or export restrictions that apply to our products. You're responsible for making sure that buying and using them is lawful where you are.</p>`),
      S("products", "The products", `<p>We sell two products, each described in full on its product page, including every file and page:</p><ul><li><a href="/products/${planner.slug}/">${esc(planner.name)}</a>: ${esc(planner.description)}</li><li><a href="/products/${bundle.slug}/">${esc(bundle.name)}</a>: ${esc(bundle.description)} It includes the complete ${esc(planner.name)}.</li></ul><p>The products are digital content: PDF files (in A4 and US Letter sizes) and, in the bundle, editable XLSX spreadsheets. No physical item is shipped.</p><p>Product images are made from the actual files. Colors may look slightly different on your screen or printer, and spreadsheet apps can display the same file a little differently; see <a href="#compatibility">section 8</a>.</p><p>Our products are organizational templates. They aren't legal, financial, tax, medical or other professional advice, and they don't guarantee any particular productivity, business or financial result.</p><p>We may improve the files from time to time. If we change a product after you've bought it, you can keep using the version you bought, and we'll send you a corrected version of any file we've fixed if you ask.</p>`),
      S("prices", "Prices, currency and taxes", `<ul><li><strong>Prices.</strong> ${listJoin(prices(ctx))}. The price that applies is the one shown in the order summary when you pay.</li><li><strong>Currency.</strong> All prices are in US dollars (USD) and you're charged in USD. If your card is in another currency, your bank converts the amount and may charge a foreign transaction or conversion fee. That fee is set by your bank, not by us.</li><li><strong>Taxes.</strong> Prices include any sales tax, VAT or GST that we're required to collect. The price shown is the total you pay. We don't add tax, shipping or any other fee at checkout.</li><li><strong>One-time payments.</strong> Each product is a single payment. We don't offer subscriptions, memberships, free trials, automatic renewals, add-ons or paid upgrades, and we never charge your card again for the same order.</li><li><strong>Promotions.</strong> We don't currently run discounts, coupon codes or promotions. If we ever do, the conditions will be shown next to the offer and will apply alongside these Terms.</li><li><strong>Mistakes.</strong> If a price is clearly wrong because of an error, we'll tell you before or straight after you order. You can then cancel for a full refund. We'll never charge you more than the price you agreed to.</li></ul>`),
      S("ordering", "Ordering and payment", `<ol><li>You choose a product and open its order summary on our website. It shows the product, the seller, the price in USD, taxes and delivery.</li><li>You tick a box to agree to these Terms, and a separate box to ask for immediate delivery (see <a href="#withdrawal">section 13</a>). Neither box is ticked in advance.</li><li>You're taken to Stripe's secure checkout page, where you enter your payment details and can check the amount again before you confirm.</li></ol><p>You can go back and correct anything before you confirm payment.</p><p><strong>Payment processing.</strong> Payments are processed by Stripe, our payment provider. Your payment details are entered on Stripe's page and sent directly to Stripe, which is certified to PCI DSS Level 1. We never receive or store your full card number. We accept ${esc(listJoin(site.acceptedCards))} cards, and Stripe may offer other payment methods depending on your location. Charges appear on your statement as <strong>${esc(site.statementDescriptor)}</strong>.</p><p><strong>When the contract starts.</strong> Our contract with you is formed when your payment is confirmed and we show you your download page. We then email you an order confirmation with your order number, the product, the price, your consent to immediate delivery and a link to these Terms.</p><p><strong>Failed payments.</strong> If your payment is declined or you leave Stripe's page before paying, no order is placed and you're not charged. Any temporary hold your bank places is released by your bank.</p><p><strong>Orders we can't accept.</strong> We may refuse or cancel an order if we reasonably suspect fraud or unauthorized use of a payment card, if the order breaks the sanctions rules in <a href="#eligibility">section 3</a>, or if the price was clearly wrong. If we cancel an order you've paid for, we refund you in full.</p>`),
      S("delivery", "Delivery and access to your files", `<ul><li><strong>How.</strong> After your payment is confirmed, you're shown a download page on our website, and we email you a link to the same files. You can download each file on its own or all of them in one ZIP file.</li><li><strong>When.</strong> Normally within a few minutes of payment, and usually straight away. If you haven't received access within 24 hours, please contact us.</li><li><strong>How long.</strong> Your download link works for ${site.downloadLinkDays} days, and you can download the files as many times as you need during that time. If it expires, we'll send a new link free of charge for at least ${site.redownloadMonths} months after your purchase. Please save copies of your files.</li><li><strong>Keep your link private.</strong> It gives access to paid files. If a link appears to be shared publicly or used far more than normal, we may disable it and send you a new one.</li><li><strong>Where.</strong> Delivery is free and works anywhere we can lawfully sell (see <a href="#eligibility">section 3</a>).</li></ul><p>If delivery fails, we'll resend your files or deliver them another way, and if we can't deliver them at all, we'll refund you in full. The <a href="/refund-policy/">Delivery and Refund Policy</a> has the details.</p>`),
      S("compatibility", "Technical requirements and compatibility", `<ul><li><strong>PDF files</strong> open in any PDF reader, including the one built into web browsers. They're designed to print on A4 or US Letter paper at 100% scale, or to be written on in tablet apps that support PDF annotation. They have no fillable form fields and their printed text can't be edited.</li><li><strong>XLSX spreadsheets</strong> (bundle only) work fully in Microsoft Excel 2016 or later, Microsoft 365, Excel for the web, Google Sheets (after File › Save as Google Sheets) and LibreOffice Calc 7 or later. Apple Numbers opens them and keeps the formulas but doesn't support their color rules, so highlights and timeline bars don't appear, and drop-down lists may need recreating. The spreadsheets contain no macros.</li><li>You need a device, software and internet connection suitable for downloading and opening these files. We can't promise compatibility with software not listed here. If you're unsure, ask us before you buy.</li></ul>`),
      S("license", "Your license to use the templates", `<h3>What you may do</h3><p>When your payment is confirmed, we give you a non-exclusive, non-transferable license, with no time limit, to download, use, edit and print the templates you bought:</p><ul><li>for your own personal use; and</li><li>for internal work in your own business or organization, including by its employees and contractors when they're working for it. One purchase covers one business or organization.</li></ul><p>For that use, you may keep copies on your own devices and cloud storage and print as many copies as you need. What you write or type into the templates is yours, and you may share filled-in copies (for example, a project plan you send to a client), as long as you're not passing on a blank template for someone else to reuse.</p><h3>What you may not do</h3><ul><li>Sell, resell, sublicense, rent, lend, give away or otherwise distribute the files, or blank or editable copies of them, to anyone outside your business or organization.</li><li>Upload the files to a website, marketplace, template library, file-sharing service or any shared folder that people outside your organization can access.</li><li>Include the templates, or substantially similar copies, in any product, template pack, course or service that you sell or give away.</li><li>Present the templates as your own original design, or remove the copyright notices from them.</li><li>Use the files to create competing template products, or as data to train or fine-tune machine-learning models.</li></ul><h3>Ownership</h3><p>Buying a product gives you a license, not ownership of the designs. ${esc(site.brand)} keeps all copyright and other intellectual property rights in the templates.</p><h3>When the license ends</h3><p>If you seriously break the rules above, your license ends and you must stop using and delete the files. If we refund an order in full, the license for that order also ends, and we ask you to delete the files. We won't ask you to prove that you've deleted them.</p>`),
      S("ip", "Intellectual property", `<p>The website, the ${esc(site.brand)} name and logo, and the product designs, layouts and text belong to ${esc(site.brand)} and are protected by copyright and other laws. The fonts used in our products and on the website are licensed under the SIL Open Font License.</p><p>Names of other companies' software (such as Microsoft Excel, Google Sheets, LibreOffice and Apple Numbers) and of Stripe belong to their owners. We mention them only to describe compatibility and payment processing; it doesn't mean they're affiliated with or endorse ${esc(site.brand)}.</p>`),
      S("use", "Your responsibilities and acceptable use", `<ul><li>Use the website and the products lawfully.</li><li>Don't try to get around the website's security, access other customers' orders or download links, or interfere with the website (for example by overloading it, introducing malware, or copying it in bulk with automated tools).</li><li>Only use a payment method you're authorized to use.</li><li>You're responsible for the information you enter into the templates, for checking that a template suits your needs, and for keeping backups of your files and data.</li></ul><p>We may suspend access to the website or a download link if it's being misused.</p>`),
      S("conformity", "If something is wrong with your files", `<p>We promise that the files you buy will match their description on the product page, work as described with the software listed in <a href="#compatibility">section 8</a>, be free from defects that stop you using them normally, and be delivered as described in <a href="#delivery">section 7</a>.</p><p>If they don't, tell us. We'll fix the problem or replace the file free of charge within a reasonable time. If we can't, if we don't do it within a reasonable time, or if the problem is serious, you can choose a full refund. If the problem is minor and you'd rather keep the files, you can ask for a partial refund instead.</p><p>Please tell us as soon as you reasonably can. We don't set any deadline shorter than the one the law gives you.</p><p>These promises are in addition to your legal rights, which we can't exclude, including:</p><ul><li>in the European Union and EEA, your rights for digital content that isn't in conformity with the contract (Directive (EU) 2019/770): to have it brought into conformity, a price reduction or termination of the contract;</li><li>in the United Kingdom, your rights for digital content under the Consumer Rights Act 2015, including repair or replacement, a price reduction or a refund;</li><li>in Australia and New Zealand, the consumer guarantees that can't be excluded under the Australian Consumer Law and the Consumer Guarantees Act 1993;</li><li>in the United States, the rights given by the laws of your state.</li></ul>`),
      S("withdrawal", "Cancellation, withdrawal and refunds", `<p><strong>Our refund promise.</strong> Whatever country you're in, you can ask for a full refund within ${site.unusedRefundDays} days of purchase if you haven't downloaded any file from your order. We also refund files that are faulty or not as described (<a href="#conformity">section 12</a>), duplicate charges and charges for the wrong amount.</p><p><strong>Change of mind after download.</strong> Once you've downloaded the files, we don't offer refunds for a simple change of mind, because digital files can't be returned. This doesn't affect any right you have under the law where you live.</p><p><strong>EU, EEA and UK consumers: your right of withdrawal.</strong> You normally have 14 days from the day of the contract to withdraw from an online purchase without giving a reason. For digital content that isn't supplied on a physical medium, this right ends once supply begins, but only if you gave your express consent to immediate supply, acknowledged that you would lose the right, and we confirmed this in your order confirmation email. We ask for this consent with a separate checkbox before you pay. Supply begins when your files are made available on the download page. If supply hasn't begun, or any of those conditions isn't met, you can withdraw within the 14 days and we'll refund you in full.</p><p>To withdraw or ask for a refund, email ${mail(site)} with your order number. You may use the model withdrawal form in our <a href="/refund-policy/#withdrawal">Delivery and Refund Policy</a>, but you don't have to. Refunds go back to your original payment method; details are in that policy.</p>`),
      S("disclaimer", "No guaranteed results", `<p>Our products help you organize your work. We don't promise that using them will make you more productive or lead to any business, financial, professional or personal result. Whether a template suits your situation is your decision.</p><p>Apart from the promises in these Terms and your rights under law, the website and products are provided without other warranties, to the extent the law allows. If you're a consumer, this doesn't affect your statutory rights.</p>`),
      S("liability", "Limits on our liability", `<p>Nothing in these Terms limits or excludes our liability for death or personal injury caused by our negligence, for fraud or fraudulent misrepresentation, or for anything else that can't legally be limited or excluded, including your statutory rights as a consumer.</p><p>Subject to that:</p><ul><li>we're responsible for loss or damage you suffer that is a foreseeable result of our breaking these Terms or failing to use reasonable care and skill. We aren't responsible for loss or damage that isn't foreseeable;</li><li>if a defective file we supplied damages a device or other digital content belonging to you because we didn't use reasonable care and skill, we'll repair the damage or compensate you where the law requires it;</li><li>our products are for personal use and internal work. We aren't liable for lost profits, lost revenue, lost business opportunities or business interruption;</li><li>to the extent the law allows, our total liability for any order is limited to the amount you paid for that order.</li></ul>`),
      S("privacy", "Privacy and payment processing", `<p>Our <a href="/privacy/">Privacy Policy</a> explains what personal information we collect and how we use it. Stripe processes your payment under its own terms and <a href="https://stripe.com/privacy" rel="noopener">privacy policy</a>. We receive only limited payment details from Stripe, such as the card brand and last four digits, never your full card number.</p>`),
      S("emails", "Emails from us", `<p>By placing an order, you agree that we can email you about it: your order confirmation, download link and any messages about your order or a support request. Stripe also emails your payment receipt. We don't send marketing emails, and we'd only ever do so with your separate consent.</p>`),
      S("control", "Events outside our control", `<p>We aren't responsible for delays or failures caused by events outside our reasonable control, such as outages at our hosting or payment providers. If that happens, we'll let you know and do what we reasonably can to deliver your files. If delivery is delayed for a long time, you can cancel the order for a full refund.</p>`),
      S("changes", "Changes to these Terms", `<p>We may update these Terms, for example to reflect changes in the law or in how the store works. The current version is always on this page with its “last updated” date. The version you agreed to when you ordered applies to that order. Later changes won't reduce your rights for purchases you've already made, including the license you already have. If you'd like a copy of the version that applied to your order, ask us.</p>`),
      S("law", "Governing law and disputes", `<p>If you have a problem, please contact us first at ${mail(site)}. Most problems can be sorted out quickly, and we'll aim to resolve any complaint within 30 days.</p><p>These Terms are governed by the laws of ${esc(site.governingLaw)}, and applicable U.S. federal law, without regard to conflict-of-law rules. If you're a consumer, you also keep the protection of the mandatory laws of the country or state where you live.</p><p>Disputes may be brought in the state or federal courts located in ${esc(site.governingState)}. If you're a consumer, you may also bring proceedings in the courts where you live, where the law allows it.</p><p>Nothing in these Terms stops you from contacting your card issuer, a consumer protection authority or any other body that can help you.</p>`),
      S("general", "General", `<ul><li>If a court decides that any part of these Terms can't be enforced, the rest still applies.</li><li>We may transfer our rights and obligations under these Terms to another business, for example if the store is sold. Your rights under these Terms won't be reduced as a result.</li><li>If we don't enforce a right straight away, we can still enforce it later.</li><li>These Terms and the policies they mention are the whole agreement between you and us about your purchase.</li><li>These Terms are written in English, and the English version applies.</li></ul>`),
      S("contact", "Contact us", `<p>Questions about these Terms, an order, a download or a refund:</p>${contactTable(site)}<p>We reply to emails within ${site.replyBusinessDays} business days (Monday to Friday, ${esc(site.timeZoneLabel)}).</p>`),
    ],
  });
}

export function refunds(ctx) {
  const { site, products } = ctx;
  const days = site.unusedRefundDays;
  const fileList = products.products
    .map((p) => `<li><strong>${esc(p.name)}</strong> (${money(p.price)}): ${p.files.length} files: ${esc(listJoin(p.files.map((f) => f.name)))}.</li>`)
    .join("");
  return legalPage(ctx, {
    path: "/refund-policy/",
    title: "Delivery and Refund Policy",
    description: `${site.brand} digital delivery, refund, return and cancellation policy: instant download, ${days}-day refund if not downloaded, fixes or refunds for faulty files, EU/UK withdrawal rights and how refunds are paid.`,
    intro: `<p>This policy explains how we deliver ${esc(site.brand)}'s digital products, what to do if a download doesn't work, when you can get a refund and how refunds are paid. It forms part of our <a href="/terms/">Terms and Conditions</a>.</p>`,
    summary: [
      "Our products are digital downloads. Nothing is shipped and there are no shipping fees.",
      `Your files are available straight after payment, on screen and by email. Links work for ${site.downloadLinkDays} days, and we'll send new ones free for ${site.redownloadMonths} months.`,
      `Haven't downloaded anything yet? You can have a full refund within ${days} days, for any reason.`,
      "File faulty, won't open or not as described? We'll fix it, replace it or refund you.",
      `Refunds go back to your original payment method within ${site.refundProcessingDays} business days of approval.`,
      "Your legal rights apply on top of everything in this policy.",
    ],
    sections: [
      S("digital", "Digital products, not physical goods", `<p class="callout">Everything ${esc(site.brand)} sells is a digital product delivered by download. No physical item is ever shipped, so there are no shipping costs, delivery addresses or delivery times to wait for.</p><p>What you receive:</p><ul>${fileList}</ul><p>Each product page lists the files and their contents in full.</p>`),
      S("delivery", "How and when we deliver", `<ol><li>You pay on Stripe's secure checkout page.</li><li>As soon as Stripe confirms the payment, normally within a few seconds, you're returned to a download page on our website showing your order number and files.</li><li>We email you an order confirmation with a download link. It also records your consent to immediate delivery.</li><li>Stripe emails your payment receipt.</li></ol><p>You can download each file on its own or everything in one ZIP file. If you haven't received access within 24 hours of paying, contact us and we'll sort it out.</p><p><strong>Cost and locations.</strong> Delivery is free. We deliver anywhere we can lawfully sell, which excludes countries and regions subject to comprehensive U.S. sanctions (see section 3 of the <a href="/terms/#eligibility">Terms</a>).</p>`),
      S("access", "Download links and keeping your files", `<ul><li>Your download link works for <strong>${site.downloadLinkDays} days</strong> from purchase. You can download as many times as you need in that period.</li><li>If the link expires, email us with your order number or checkout email address and we'll send a new link free of charge, for at least <strong>${site.redownloadMonths} months</strong> after your purchase.</li><li>Please save your files somewhere safe, such as your computer and a cloud backup.</li><li>Your link is personal. If it appears to be shared publicly or used far more than normal, we may disable it and send you a new one.</li><li>If an order is refunded in full, its download link stops working.</li></ul>`),
      S("problems", "If a download fails or a file doesn't work", `<p>Most problems are fixed by downloading again, trying another browser or network, or opening the file in a different app. Our <a href="/download-help/">download help page</a> has step-by-step fixes.</p><p>If that doesn't work, or a file is damaged, incomplete or different from its description, email ${mail(site)} or call ${phone(site)}. Please include your order number, the file name and what you see. We'll reply within ${site.replyBusinessDays} business days and will:</p><ul><li>resend the files or deliver them another way if delivery failed;</li><li>send a corrected or replacement file if a file is faulty; or</li><li>refund you in full if we can't fix the problem within a reasonable time, or straight away if the problem is serious.</li></ul>`),
      S("refunds", "When you can get a refund", `<div class="table-wrap" role="region" aria-label="Refund situations" tabindex="0"><table><thead><tr><th scope="col">Situation</th><th scope="col">What we do</th><th scope="col">When to ask</th></tr></thead><tbody>
<tr><td>You haven't downloaded any file from your order</td><td>Full refund, no reason needed</td><td>Within ${days} days of purchase</td></tr>
<tr><td>A file is faulty, corrupted or won't open with the software listed for it</td><td>Fix or replace it; full refund if we can't, or if you'd rather not wait</td><td>As soon as you notice. We don't set a shorter deadline than the law allows</td></tr>
<tr><td>The product is materially different from its description</td><td>Full refund, or a replacement if you prefer</td><td>As soon as you notice</td></tr>
<tr><td>We couldn't deliver your files</td><td>Full refund</td><td>Any time</td></tr>
<tr><td>You were charged twice or charged the wrong amount</td><td>Refund of the duplicate charge or the difference</td><td>As soon as you notice</td></tr>
<tr><td>You've downloaded the files and changed your mind</td><td>Not normally refunded (see section 6), unless the law where you live requires it</td><td>n/a</td></tr>
<tr><td>Your card was used without your permission</td><td>Contact your card issuer straight away, and please tell us too so we can help</td><td>Straight away</td></tr>
</tbody></table></div>`),
      S("change-of-mind", "Change of mind after downloading", `<p>Digital files can't be returned once they've been downloaded, so we don't normally refund a simple change of mind after download. That's why we offer a full refund for any reason before you download, and why each product page lists every file and page and shows previews of the real pages before you buy.</p><p>This never limits your rights for faulty or misdescribed files, or any other right you have under the law where you live.</p>`),
      S("withdrawal", "Your right of withdrawal (EU, EEA and UK consumers)", `<p>If you're a consumer in the European Union, the European Economic Area or the United Kingdom, you normally have the right to withdraw from an online purchase within 14 days of the day the contract is made, without giving a reason.</p><h3>When the right ends for digital files</h3><p>For digital content that isn't supplied on a physical medium, the right of withdrawal ends once supply begins, if all of these apply:</p><ol><li>you expressly consented to supply starting straight away, within the withdrawal period;</li><li>you acknowledged that you would lose your right of withdrawal once supply began; and</li><li>we confirmed your consent and acknowledgment in your order confirmation email.</li></ol><p>Before you pay, our order page asks for this consent with its own checkbox, separate from accepting our Terms, and it is never ticked in advance. Supply begins when your files are made available on the download page. If supply hasn't begun, or any of the conditions above isn't met, you keep your right to withdraw for 14 days.</p><h3>How to withdraw</h3><p>Send us a clear statement that you want to withdraw, by email to ${mail(site)} or by post to ${esc(addressInline(site))}, before the 14 days end. You can use the model form below, but you don't have to.</p><h3>What happens next</h3><p>We'll refund all payments we received from you for that order within 14 days of receiving your withdrawal, using the same payment method you used, unless you expressly agree otherwise. You won't pay any fee for the refund.</p><h3>Model withdrawal form</h3><div class="model-form"><p>(Complete and return this form only if you wish to withdraw from the contract.)</p><p>To: ${esc(sellerName(site))}, ${esc(addressInline(site))}, ${esc(site.email)}</p><p>I/We (*) hereby give notice that I/We (*) withdraw from my/our (*) contract of sale of the following digital content:</p><p>Ordered on (*) / received on (*):</p><p>Order number:</p><p>Name of consumer(s):</p><p>Address of consumer(s):</p><p>Signature of consumer(s) (only if this form is sent on paper):</p><p>Date:</p><p>(*) Delete as appropriate.</p></div><p class="small">This section is in addition to our own ${days}-day refund for orders you haven't downloaded, which applies wherever you live.</p>`),
      S("statutory", "Your legal rights for faulty or misdescribed files", `<p>Whatever this policy says, you keep the rights the law gives you. Depending on where you live, these include:</p><ul><li><strong>European Union and EEA:</strong> if digital content isn't in conformity with the contract, you're entitled to have it brought into conformity, or to a price reduction or termination of the contract with a refund (Directive (EU) 2019/770).</li><li><strong>United Kingdom:</strong> digital content must be of satisfactory quality, fit for purpose and as described. If it isn't, you're entitled to a repair or replacement and, if that's not possible or doesn't fix the problem, a price reduction or refund (Consumer Rights Act 2015).</li><li><strong>Australia and New Zealand:</strong> consumer guarantees under the Australian Consumer Law and the Consumer Guarantees Act 1993 that can't be excluded.</li><li><strong>United States:</strong> the rights given by the consumer protection laws of your state.</li></ul>`),
      S("how-to-ask", "How to ask for a refund or a fix", `<ol><li>Email ${mail(site)} (or call ${phone(site)}).</li><li>Include your order number (it starts with CW- and is in your confirmation email) or the email address you used at checkout.</li><li>Tell us which product it's about and why you're asking. For a faulty file, say which file and what you see; a screenshot helps but isn't required.</li></ol><p>We'll reply within ${site.replyBusinessDays} business days. If we need more information, we'll tell you exactly what. If we can't approve a request, we'll explain why and what else we can do.</p>`),
      S("payment", "How refunds are paid", `<ul><li>Refunds are made to the original payment method through Stripe. We can't refund to a different card or account.</li><li>We refund the full amount you paid in US dollars, including any tax, unless you're getting a partial refund you asked for. We don't charge any fee for refunds.</li><li>We issue approved refunds within ${site.refundProcessingDays} business days. Your bank or card issuer then usually takes 5 to 10 business days to show the refund on your statement.</li><li>If your card is in another currency, exchange rates may have changed since you paid, so the amount in your currency may differ slightly. We refund the full USD amount.</li><li>When an order is refunded in full, its download link stops working and the license for those files ends. We ask you to delete the files, but we won't ask you to prove it.</li></ul>`),
      S("cancellations", "Cancellations", `<p>There are no subscriptions, so there's never anything to cancel to stop future charges, and we never charge you again.</p><p>If you leave Stripe's checkout page before paying, no order is placed. After you've paid, you can cancel by asking for a refund under this policy, for example within ${days} days if you haven't downloaded anything.</p>`),
      S("returns", "Returns", `<p>Our products are digital files, so there's nothing to send back. You don't need to return anything to get a refund under this policy.</p>`),
      S("disputes", "Problems with a charge", `<p>Our charges appear on card statements as <strong>${esc(site.statementDescriptor)}</strong>. If you don't recognize a charge or think something has gone wrong, please contact us before disputing it with your bank. We can usually fix it faster, and contacting us doesn't affect your right to dispute a charge with your card issuer.</p>`),
      S("contact", "Contact", `${contactTable(site)}<p>We reply to emails within ${site.replyBusinessDays} business days (Monday to Friday, ${esc(site.timeZoneLabel)}).</p>`),
    ],
  });
}

export function privacy(ctx) {
  const { site } = ctx;
  return legalPage(ctx, {
    path: "/privacy/",
    title: "Privacy Policy",
    description: `How ${site.brand} collects, uses, shares and protects personal information when you visit ${site.domain}, buy a digital product or contact support, and how to use your privacy rights.`,
    intro: `<p>This policy explains what personal information ${esc(site.brand)} collects when you visit ${esc(site.domain)}, buy one of our products or contact us; why we use it; who we share it with; how long we keep it; and the choices and rights you have. We collect only what we need to sell and deliver our products and to help you.</p>`,
    summary: [
      "When you buy, we collect your name, email address, billing country and postal code, and order details.",
      "Your card details go straight to Stripe. We never see or store your full card number.",
      "We don't use analytics, advertising or tracking tools, and our website doesn't set any cookies of its own.",
      "We don't sell or share your personal information for advertising, and we don't send marketing emails.",
      `You can ask to see, correct, delete or export your information by emailing ${mail(site)}.`,
    ],
    sections: [
      S("who", "Who we are", `<p>${esc(sellerName(site))} (“${esc(site.brand)}”, “we”, “us”) is responsible for the personal information described in this policy. Under data protection laws such as the EU and UK General Data Protection Regulation (GDPR), we are the “controller” of that information.</p>${contactTable(site)}<p>For privacy questions or requests, email ${mail(site)} with “Privacy” in the subject line.</p>`),
      S("collect", "What we collect", `<h3>When you visit the website</h3><p>Our hosting provider, Cloudflare, processes technical information needed to deliver the website and protect it from attacks: your IP address, browser and device type, the pages you request and the time of each request. We don't use analytics, advertising networks, social media pixels or other tracking tools, and we don't load fonts or scripts from third parties.</p><h3>When you buy</h3><ul><li><strong>Contact details:</strong> your name and email address, entered on Stripe's checkout page.</li><li><strong>Billing details:</strong> your billing country and postal code, and any other billing address details Stripe asks for to process the payment and work out tax.</li><li><strong>Order details:</strong> the product, price, tax, currency, date and time, order number, and the status of your payment and any refund.</li><li><strong>Payment details:</strong> you enter your card or other payment details on Stripe's page, not ours. We never receive your full card number or security code. Stripe gives us limited details such as the card brand, the last four digits, the expiry date and the card's country.</li><li><strong>Your checkout choices:</strong> a record that you accepted our Terms and consented to immediate delivery, with the date, time and version of the Terms. We keep this as evidence for consumer law purposes.</li><li><strong>Download records:</strong> when files are downloaded with your link, we record the date, time, IP address and browser type. We use this to deliver your files, to see whether files have been downloaded when you ask for a refund, and to prevent misuse of download links.</li></ul><h3>When you contact us</h3><p>Your name, email address, phone number if you call, and whatever you tell us in your message, including any attachments.</p><h3>From other sources</h3><p>Stripe tells us whether a payment succeeded, failed, was refunded or was disputed, and may share the result of its fraud checks.</p>`),
      S("use", "How we use it, and our legal bases", `<div class="table-wrap" role="region" aria-label="How we use personal information" tabindex="0"><table><thead><tr><th scope="col">What we do</th><th scope="col">Information used</th><th scope="col">Legal basis (EEA and UK)</th></tr></thead><tbody>
<tr><td>Take your payment, deliver your files and send order emails</td><td>Contact, billing, order and payment details; download records</td><td>Performing our contract with you</td></tr>
<tr><td>Answer questions, fix delivery problems and handle refunds</td><td>Contact, order and support information; download records</td><td>Performing our contract with you; our legitimate interest in helping customers</td></tr>
<tr><td>Keep tax and accounting records</td><td>Order and billing details</td><td>Complying with legal obligations</td></tr>
<tr><td>Keep evidence of your checkout consents</td><td>Checkout choices</td><td>Complying with legal obligations; our legitimate interest in being able to show what you agreed to</td></tr>
<tr><td>Prevent fraud, protect download links and keep the website secure</td><td>Technical information, payment and order details, download records</td><td>Our legitimate interests in preventing fraud and protecting our business and customers</td></tr>
<tr><td>Handle legal claims and payment disputes</td><td>Any of the above, as needed</td><td>Our legitimate interest in establishing or defending legal claims</td></tr>
</tbody></table></div><p>You don't have to give us personal information, but we can't sell you a product without an email address to deliver it to and the details Stripe needs to take the payment.</p>`),
      S("dont", "What we don't do", `<ul><li>We don't sell your personal information, and we don't share it for cross-context behavioral advertising or targeted advertising.</li><li>We don't use analytics or advertising cookies, tracking pixels or similar tools.</li><li>We don't send marketing emails or newsletters. If we ever offer one, it will be opt-in only.</li><li>We don't make decisions about you based solely on automated processing that have legal or similarly significant effects, except for Stripe's automated fraud screening described below.</li></ul>`),
      S("stripe", "Payments and Stripe", `<p>Payments are processed by Stripe. When you pay, you enter your payment details on Stripe's checkout page, and Stripe receives them directly. Stripe also collects information about the device and browser you use on its checkout page, including through cookies and similar technologies, and uses it to process the payment, detect and prevent fraud and keep its services secure. Stripe states that it doesn't use this fraud-detection information for advertising.</p><p>For some of this processing, Stripe acts as an independent controller under its own policies. You can read <a href="https://stripe.com/privacy" rel="noopener">Stripe's privacy policy</a> and <a href="https://stripe.com/cookies-policy/legal" rel="noopener">Stripe's cookie policy</a>.</p><p>Our own website doesn't load any Stripe scripts; Stripe only collects this information on its checkout page. Stripe's fraud screening is automated and may decline a payment that looks risky. If you think a payment was declined by mistake, contact us and we'll look into it with you.</p>`),
      S("share", "Who we share it with", `<p>We share personal information only with the following, and only as far as necessary for the purposes above:</p><ul><li><strong>Stripe</strong> (payment processing, receipts, fraud prevention and payment disputes), as described in section 5.</li><li><strong>Cloudflare, Inc.</strong> (website hosting, security, and storage of our product files and order records). See <a href="https://www.cloudflare.com/privacypolicy/" rel="noopener">Cloudflare's privacy policy</a>.</li><li><strong>Our email service providers</strong>, which deliver order emails and host our support mailbox.</li><li><strong>Professional advisers and authorities:</strong> accountants, tax advisers and lawyers when needed, and government authorities or courts when the law requires it.</li><li><strong>A buyer of our business</strong>, if the business is ever sold or transferred. The information would stay protected by this policy.</li></ul><p>Our service providers may use your information only to provide their services to us, except where they act as independent controllers, as Stripe does for some processing under its own privacy policy.</p>`),
      S("transfers", "International transfers", `<p>${esc(site.brand)} is based in the United States, and our service providers may process information in the United States and other countries. If you're in the EEA, the UK or Switzerland, your information is transferred to the United States. Where the law requires it, our providers rely on recognized safeguards such as the European Commission's Standard Contractual Clauses or the EU-U.S. Data Privacy Framework and its UK and Swiss extensions. You can ask us for more information about these safeguards.</p>`),
      S("retention", "How long we keep it", `<div class="table-wrap" role="region" aria-label="Retention periods" tabindex="0"><table><thead><tr><th scope="col">Information</th><th scope="col">How long</th></tr></thead><tbody>
<tr><td>Order, payment and tax records, and checkout consent records</td><td>7 years after the purchase, to meet tax and accounting requirements and to deal with any claims</td></tr>
<tr><td>Download records</td><td>${site.redownloadMonths} months after the purchase, while we still provide new download links</td></tr>
<tr><td>Support emails and call notes</td><td>3 years after we last hear from you</td></tr>
<tr><td>Technical logs held by our hosting provider</td><td>A short period set by Cloudflare for security and operations</td></tr>
</tbody></table></div><p>After these periods we delete the information or make it anonymous. We may keep it longer if the law requires it or if it's needed for a legal claim.</p>`),
      S("security", "How we protect it", `<p>The whole website uses encrypted HTTPS connections. Card payments are made on Stripe's checkout page; Stripe is certified to PCI DSS Level 1. Product files and order records are stored privately and can only be reached through a valid download link or by us. Access to our business accounts is restricted to the people who need it. No system is perfectly secure, but we take reasonable measures to protect your information, and we'll tell you and the authorities about a data breach where the law requires it.</p>`),
      S("your-rights", "Your rights", `<h3>Everyone</h3><p>Wherever you live, you can ask us to tell you what personal information we hold about you, to give you a copy, to correct it, or to delete it (unless we have to keep it, for example for tax records). We won't treat you differently for using your rights.</p><h3>EEA, UK and Switzerland</h3><p>You also have the right to restrict or object to our processing, including processing based on our legitimate interests, and to receive your information in a portable format. You can complain to your local data protection authority (in the UK, the Information Commissioner's Office), though we'd appreciate the chance to deal with your concern first.</p><h3>United States</h3><p>Depending on your state (for example California, Colorado, Connecticut, Oregon, Texas, Virginia and other states with consumer privacy laws), you may have the right to know, access, correct and delete your personal information, to get a portable copy, and to opt out of its sale, its sharing for targeted advertising, and profiling. We don't sell or share personal information or use it for targeted advertising or profiling.</p><p><strong>California notice.</strong> In the last 12 months we collected these categories of personal information: identifiers (name, email address, IP address), customer records (billing details), commercial information (products bought), and internet activity (requests to our website and download records). We collected them from you, from your device and from Stripe, for the purposes in section 3, and disclosed them only to the service providers in section 6. We haven't sold or shared personal information and have no actual knowledge of selling or sharing the personal information of consumers under 16. We keep each category for the periods in section 8.</p><h3>How to make a request</h3><p>Email ${mail(site)} or call ${phone(site)}. To protect your information, we'll check it's you, usually by asking you to write from the email address used for your order. You can also use an authorized agent, who will need your signed permission. We'll respond within one month in the EEA and UK, and within 45 days in the United States, and tell you if we need more time as the law allows. If we refuse a request, we'll explain why. In the United States you can appeal by replying to our decision, and if you're unhappy with the outcome you can contact your state attorney general.</p><h3>Global Privacy Control</h3><p>We don't track you across websites. If your browser sends a Global Privacy Control signal, we treat it as a request to opt out of the sale or sharing of your personal information, which we don't do anyway.</p>`),
      S("cookies", "Cookies", `<p>Our website doesn't set any cookies of its own. Our hosting provider may set strictly necessary security cookies, and Stripe sets cookies on its checkout page. Our <a href="/cookies/">Cookie Policy</a> lists them.</p>`),
      S("children", "Children", `<p>Our website and products are intended for adults and aren't directed at children. We don't knowingly collect personal information from children under 16. If you believe a child has given us personal information, contact us and we'll delete it.</p>`),
      S("changes", "Changes to this policy", `<p>We'll update this policy if we change how we handle personal information, for example if we start using a new service provider. The current version is always on this page with its “last updated” date. If a change significantly affects you, we'll make it clear on this page before it takes effect.</p>`),
      S("contact", "Contact", `<p>Questions or requests about your personal information:</p>${contactTable(site)}`),
    ],
  });
}

export function cookies(ctx) {
  const { site } = ctx;
  return legalPage(ctx, {
    path: "/cookies/",
    title: "Cookie Policy",
    description: `${site.brand}'s website sets no cookies of its own and uses no analytics or advertising trackers. This policy lists the strictly necessary cookies set by our hosting and payment providers.`,
    intro: `<p>This policy explains which cookies and similar technologies are used when you visit ${esc(site.domain)} or pay for an order.</p>`,
    summary: [
      `The ${esc(site.brand)} website sets no cookies and stores nothing in your browser.`,
      "We don't use analytics, advertising, social media or other tracking tools.",
      "Our hosting provider, Cloudflare, may set strictly necessary security cookies.",
      "When you pay, Stripe sets cookies on its own checkout page for security and fraud prevention.",
      "Because only strictly necessary cookies are used, there's no cookie banner to accept.",
    ],
    sections: [
      S("what", "What cookies are", `<p>Cookies are small text files a website stores in your browser. Similar technologies include local storage and tracking pixels. Some are strictly necessary to provide a service you ask for, such as keeping a website secure. Others are used for analytics or advertising; we don't use those.</p>`),
      S("ours", "Cookies we set", `<p>None. Our website doesn't set cookies, doesn't use local storage or session storage, and doesn't include analytics, advertising pixels, social media buttons, embedded videos or maps. Our fonts and images are served from our own website, not from third-party services.</p>`),
      S("hosting", "Security cookies from our hosting provider", `<p>Our website is hosted by Cloudflare. To protect it from automated attacks and abuse, Cloudflare may set the following strictly necessary cookies. They aren't used to track you across websites.</p><div class="table-wrap" role="region" aria-label="Cloudflare cookies" tabindex="0"><table><thead><tr><th scope="col">Name</th><th scope="col">Purpose</th><th scope="col">Duration</th></tr></thead><tbody>
<tr><td><code>__cf_bm</code></td><td>Distinguishes people from automated bots</td><td>30 minutes</td></tr>
<tr><td><code>cf_clearance</code></td><td>Remembers that you passed a security check</td><td>Set by the security check, usually 30 minutes</td></tr>
<tr><td><code>_cfuvid</code></td><td>Applies rate limits fairly between visitors</td><td>End of browser session</td></tr>
</tbody></table></div><p>These are only set when the related security features are active. See <a href="https://developers.cloudflare.com/fundamentals/reference/policies-compliances/cloudflare-cookies/" rel="noopener">Cloudflare's cookie information</a>.</p>`),
      S("stripe", "Cookies on Stripe's checkout page", `<p>When you continue to payment, you leave our website for Stripe's checkout page. Stripe uses cookies and similar technologies there to process your payment, keep it secure and prevent fraud. These are set by Stripe on its own website, not by us. See our <a href="/privacy/#stripe">Privacy Policy</a> and <a href="https://stripe.com/cookies-policy/legal" rel="noopener">Stripe's cookie policy</a>.</p>`),
      S("consent", "Why there's no cookie banner", `<p>Privacy laws such as the EU ePrivacy rules and the UK's PECR require consent for cookies that aren't strictly necessary. Because the only cookies involved are strictly necessary for security and for completing a payment you ask for, no consent banner is needed. If we ever add a tool that needs your consent, we'll update this policy first and ask for your consent before it's used.</p>`),
      S("control", "How to control cookies", `<p>You can block or delete cookies in your browser settings. Blocking Cloudflare's security cookies may mean you're asked to complete a security check, and blocking cookies on Stripe's page may stop the payment from working.</p>`),
      S("contact", "Changes and contact", `<p>We'll update this policy if the cookies used change, and show the date at the top. Questions: ${mail(site)}.</p>`),
    ],
  });
}

export function legalNotice(ctx) {
  const { site, products } = ctx;
  return legalPage(ctx, {
    path: "/legal-notice/",
    title: "Legal Notice",
    description: `Business information for ${site.brand}: business name, address, contact details, what we sell, payment processing and credits.`,
    intro: `<p>Information about the business that operates ${esc(site.domain)}.</p>`,
    sections: [
      S("business", "Business information", `${contactTable(site)}<p>The business name ${esc(site.brand)} is used on this website, on our products, in our emails and on card statements (as ${esc(site.statementDescriptor)}). The website address is ${esc(site.domain)}.</p>`),
      S("activity", "What we do", `<p>${esc(site.brand)} sells two original digital products directly to customers: ${listJoin(prices(ctx))}. Both are downloadable files. We don't sell physical goods, subscriptions or services, and we don't sell on behalf of anyone else.</p>`),
      S("responsible", "Responsible for content", `<p>${esc(sellerName(site))}, ${esc(addressInline(site))}.</p>`),
      S("payments", "Payment processing", `<p>Card payments are processed by Stripe on its secure checkout page. Stripe is our payment provider only; it isn't otherwise connected with ${esc(site.brand)} and doesn't endorse our products.</p>`),
      S("complaints", "Complaints and disputes", `<p>If you have a complaint, please email ${mail(site)} or call ${phone(site)}. We aim to resolve complaints within 30 days. We don't currently take part in an alternative dispute resolution scheme. Your rights are explained in our <a href="/terms/#law">Terms and Conditions</a> and <a href="/refund-policy/">Delivery and Refund Policy</a>.</p>`),
      S("credits", "Credits and trademarks", `<ul><li>All product designs, website text and product images are by ${esc(site.brand)}. Product images are made from the actual product files.</li><li>Fonts: Fraunces and Atkinson Hyperlegible Next, used under the SIL Open Font License 1.1 (<a href="/assets/fonts/OFL-Fraunces.txt">Fraunces license</a>, <a href="/assets/fonts/OFL-AtkinsonHyperlegibleNext.txt">Atkinson Hyperlegible Next license</a>).</li><li>Stripe, Microsoft Excel, Google Sheets, Apple Numbers, LibreOffice and Cloudflare are trademarks of their respective owners and are mentioned only to describe how our store and products work.</li></ul>`),
      S("links", "Links to other websites", `<p>We link to a few other websites, such as Stripe's and Cloudflare's privacy policies. We aren't responsible for their content.</p>`),
    ],
  });
}

export function accessibility(ctx) {
  const { site } = ctx;
  return legalPage(ctx, {
    path: "/accessibility/",
    title: "Accessibility Statement",
    description: `${site.brand}'s accessibility statement: what we've done to make ${site.domain} usable for everyone, known limitations and how to ask for help.`,
    intro: `<p>We want everyone to be able to use ${esc(site.domain)}, find out about our products and buy them, whatever device or assistive technology they use.</p>`,
    sections: [
      S("target", "Our goal", `<p>We aim to meet the Web Content Accessibility Guidelines (WCAG) 2.2 at level AA. We haven't had the website independently audited, so we don't claim full conformance, but we design and check every page against those guidelines.</p>`),
      S("done", "What we've done", `<ul><li>Pages use clear headings, landmarks and a “skip to main content” link, so they work well with screen readers.</li><li>Everything can be used with a keyboard, with a clearly visible focus outline.</li><li>Text and controls meet WCAG AA color contrast, and color is never the only way information is shown.</li><li>Body text uses Atkinson Hyperlegible Next, a typeface designed for readers with low vision, at a comfortable size and line length.</li><li>Pages reflow on small screens and when zoomed to 400%, without scrolling sideways.</li><li>Images have text alternatives, and product pages describe every page and file in text, not just in pictures.</li><li>Form controls have visible labels, and nothing is pre-selected for you.</li><li>There's no auto-playing media, no flashing content and no time limits.</li></ul>`),
      S("checks", "How we check", `<p>Each page is checked with automated accessibility testing (axe-core), keyboard-only navigation, browser zoom and narrow mobile screen widths. This statement was last reviewed on ${esc(site.policiesUpdatedDisplay)}.</p>`),
      S("limits", "Known limitations", `<ul><li><strong>Printable PDFs.</strong> The planner and printables are worksheets designed to be printed and written on. They aren't tagged for screen readers. Each product page describes every page in text, and we're happy to describe any page in more detail.</li><li><strong>Spreadsheets.</strong> The spreadsheets work with screen readers in Excel, Google Sheets and LibreOffice. The timeline uses colored cells to show bars; the start and due dates they're based on are also shown as text in the same rows.</li><li><strong>Payment page.</strong> Payment takes place on Stripe's checkout page, which is provided and maintained by Stripe.</li></ul>`),
      S("help", "Need help or found a problem?", `<p>If anything on this website is hard to use, or you need information in a different format, email ${mail(site)} or call ${phone(site)}. Tell us the page and what went wrong. We'll reply within ${site.replyBusinessDays} business days and help you get what you need, including helping you complete a purchase if a barrier is in the way.</p>`),
    ],
  });
}
